import java.io.*;

public class Main {
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = System.in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static int readInt() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        int x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = readByte();
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = readInt(), m = readInt();
        int[] s = new int[n], e = new int[n], head = new int[n], degree = new int[n], to = new int[m], next = new int[m], queue = new int[n];
        for (int i = 0; i < n; i++) {
            s[i] = readInt();
            e[i] = readInt();
            head[i] = -1;
        }
        // Flat adjacency lists and in-degrees.
        for (int i = 0; i < m; i++) {
            int u = readInt() - 1, v = readInt() - 1;
            to[i] = v;
            next[i] = head[u];
            head[u] = i;
            degree[v]++;
        }
        int first = 0, last = 0;
        for (int i = 0; i < n; i++) if (degree[i] == 0) queue[last++] = i;
        // Kahn's order: children get start > parent's start and end < parent's end.
        while (first < last) {
            int u = queue[first++];
            for (int k = head[u]; k != -1; k = next[k]) {
                int v = to[k];
                s[v] = Math.max(s[v], s[u] + 1);
                e[v] = Math.min(e[v], e[u] - 1);
                if (--degree[v] == 0) queue[last++] = v;
            }
        }
        boolean ok = last == n; // otherwise there is a cycle
        for (int i = 0; i < n && ok; i++) if (s[i] >= e[i]) ok = false;
        if (!ok) {
            System.out.println("IMPOSSIBLE");
            return;
        }
        StringBuilder sb = new StringBuilder(n * 16);
        for (int i = 0; i < n; i++) sb.append(s[i]).append(' ').append(e[i]).append('\n');
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        out.write(sb.toString());
        out.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() int32 {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		var x int32
		for err == nil && c > ' ' {
			x = x*10 + int32(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	n, m := int(readInt()), int(readInt())
	s, e := make([]int32, n), make([]int32, n)
	head, degree, queue := make([]int32, n), make([]int32, n), make([]int32, 0, n)
	to, next := make([]int32, m), make([]int32, m)
	for i := 0; i < n; i++ {
		s[i], e[i], head[i] = readInt(), readInt(), -1
	}
	// Flat adjacency lists and in-degrees.
	for i := 0; i < m; i++ {
		u, v := readInt()-1, readInt()-1
		to[i], next[i], head[u] = v, head[u], int32(i)
		degree[v]++
	}
	for i := 0; i < n; i++ {
		if degree[i] == 0 {
			queue = append(queue, int32(i))
		}
	}
	// Kahn's order: children get start > parent's start and end < parent's end.
	for first := 0; first < len(queue); first++ {
		u := queue[first]
		for k := head[u]; k != -1; k = next[k] {
			v := to[k]
			s[v] = max(s[v], s[u]+1)
			e[v] = min(e[v], e[u]-1)
			degree[v]--
			if degree[v] == 0 {
				queue = append(queue, v)
			}
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	ok := len(queue) == n // otherwise there is a cycle
	for i := 0; i < n && ok; i++ {
		if s[i] >= e[i] {
			ok = false
		}
	}
	if !ok {
		w.WriteString("IMPOSSIBLE\n")
		return
	}
	line := make([]byte, 0, 32)
	for i := 0; i < n; i++ {
		line = strconv.AppendInt(line[:0], int64(s[i]), 10)
		line = append(line, ' ')
		line = strconv.AppendInt(line, int64(e[i]), 10)
		line = append(line, '\n')
		w.Write(line)
	}
}
